const canonicalWallet = (value) => {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string') return value.trim();
  return value.toString().trim();
};

const canonicalOrNull = (value) => {
  const canonical = canonicalWallet(value);
  return canonical.length > 0 ? canonical : null;
};

const LINKED_AUTH_WALLET_PREFIX = 'linked_auth:';

const isLinkedAuthPlaceholderWallet = (walletAddress) => {
  const normalized = canonicalOrNull(walletAddress);
  return Boolean(
    normalized && normalized.toLowerCase().startsWith(LINKED_AUTH_WALLET_PREFIX),
  );
};

const isRealWalletAddress = (walletAddress) => {
  const normalized = canonicalOrNull(walletAddress);
  return Boolean(normalized && !isLinkedAuthPlaceholderWallet(normalized));
};

const publicWalletAddressOrNull = (walletAddress) => {
  const normalized = canonicalOrNull(walletAddress);
  return isRealWalletAddress(normalized) ? normalized : null;
};

const walletsEqual = (a, b) => canonicalWallet(a) === canonicalWallet(b);

const walletRoom = (wallet) => {
  const canonical = canonicalWallet(wallet);
  return canonical ? `user:${canonical}` : null;
};

const walletMatchClause = (column, paramIndex) => `(${column} = $${paramIndex}::text OR lower(${column}) = lower($${paramIndex}::text))`;

module.exports = {
  canonicalWallet,
  canonicalOrNull,
  isLinkedAuthPlaceholderWallet,
  isRealWalletAddress,
  publicWalletAddressOrNull,
  walletsEqual,
  walletRoom,
  walletMatchClause,
};
